Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    static class FastReader {
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int nextInt() throws IOException {
            int c = br.read();
            while (c <= ' ') {
                c = br.read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = br.read();
            }
            int ret = 0;
            while (c >= '0' && c <= '9') {
                ret = ret * 10 + c - '0';
                c = br.read();
            }
            return neg ? -ret : ret;
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader();
        int w = in.nextInt();
        int m = in.nextInt();
        boolean ans = get(w, m) || get(w, m - 1) || get(w, m + 1);
        System.out.println(ans ? "YES" : "NO");
    }

    static boolean get(int w, int m) {
        if (m == 0) return true;
        if (m % w != 0) return false;
        m /= w;
        if (m == 1) return true;
        return get(w, m) || get(w, m - 1) || get(w, m + 1);
    }
}
